```python
# -*- coding: utf-8 -*-
import sys

LIMIT = 10**9

def main():
    input = sys.stdin.readline
    T = int(input())
    for _ in range(T):
        n, q = map(int, input().split())
        a = list(map(int, input().split()))
        ans = [0]*(n+1)  # ans[len] 表示所有长度为 len 的区间答案，1-indexed

        i = 0
        while i < n:
            if a[i] == 0:
                # 包含 0 的区间乘积为 0，跳过
                i += 1
                continue
            j = i
            while j < n and a[j] != 0:
                j += 1
            lenSeg = j - i
            seg = a[i:j]
            # 判断是否全为 1
            if all(x == 1 for x in seg):
                # 全 1 段，贡献直接为 (L - len + 1)
                for L in range(1, lenSeg+1):
                    ans[L] += (lenSeg - L + 1)
            else:
                # 非全 1 段，对每个起点单独累乘，直到乘积超过 LIMIT
                for start in range(lenSeg):
                    prod = 1
                    for end in range(start, lenSeg):
                        # 判断乘积是否会超过 LIMIT
                        if prod > LIMIT // seg[end]:
                            break
                        prod *= seg[end]
                        if prod > LIMIT:
                            break
                        length = end - start + 1
                        ans[length] += prod
            i = j

        out = []
        for _ in range(q):
            L = int(input())
            out.append(str(ans[L]))
        sys.stdout.write("\n".join(out) + "\n")

if __name__ == '__main__':
    main()

