import java.io.*;
import java.util.*;
public class Main {
    static final long LIMIT = 1000000000L;
    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));
        int T = Integer.parseInt(br.readLine());
        while(T-- > 0){
            String[] parts = br.readLine().split(" ");
            int n = Integer.parseInt(parts[0]);
            int q = Integer.parseInt(parts[1]);
            String[] arrStr = br.readLine().split(" ");
            long[] a = new long[n];
            for(int i = 0; i < n; i++){
                a[i] = Long.parseLong(arrStr[i]);
            }
            // ans[len] 表示所有长度为 len 的区间答案，1-indexed
            long[] ans = new long[n+1];
            int i = 0;
            while(i < n){
                if(a[i] == 0){
                    // 包含 0 的区间乘积为 0，直接跳过
                    i++;
                    continue;
                }
                int j = i;
                while(j < n && a[j] != 0) j++;
                int lenSeg = j - i;
                long[] seg = new long[lenSeg];
                for(int k = 0; k < lenSeg; k++){
                    seg[k] = a[i+k];
                }
                boolean allOnes = true;
                for(long num : seg){
                    if(num != 1){
                        allOnes = false;
                        break;
                    }
                }
                if(allOnes){
                    // 全 1 段，直接计算贡献
                    for(int L = 1; L <= lenSeg; L++){
                        ans[L] += (lenSeg - L + 1);
                    }
                } else {
                    // 非全 1 段，从每个起点单独累乘，直到乘积超过 LIMIT
                    for(int start = 0; start < lenSeg; start++){
                        long prod = 1;
                        for(int end = start; end < lenSeg; end++){
                            if(prod > LIMIT / seg[end]){
                                break;
                            }
                            prod *= seg[end];
                            if(prod > LIMIT) break;
                            int len = end - start + 1;
                            ans[len] += prod;
                        }
                    }
                }
                i = j;
            }
            for(int k = 0; k < q; k++){
                int L = Integer.parseInt(br.readLine());
                out.println(ans[L]);
            }
        }
        out.flush();
        out.close();
    }
}

